function prepareCampaign({
  website_url,
  campaign_id,
  campaign_source,
  campaign_medium,
  campaign_name,
  campaign_term,
  baseId,
  tableId,
}) {
  const site = website_url.trim();
  const parts = /^(https?:\/\/)([a-z0-9.-]+(?::\d{1,5})?)(\/[^?#]*)?(?:\?([^#]*))?(#.*)?$/i.exec(
    site,
  );
  if (!parts || /[\s\\\x00-\x1f\x7f]/.test(site) || /%(?![a-f0-9]{2})/i.test(site)) {
    throw new Error("Enter a complete HTTP or HTTPS campaign URL without credentials");
  }
  const [host, port] = parts[2].split(":");
  if (
    !host
      .split(".")
      .filter((label, index, all) => label || index !== all.length - 1)
      .every((label) => /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/i.test(label)) ||
    !/[a-z0-9]/i.test(host) ||
    (port && (Number(port) < 1 || Number(port) > 65535))
  ) {
    throw new Error("Enter a campaign URL with a valid hostname and port");
  }
  if (!/^app[A-Za-z0-9]{14}$/.test(baseId) || !/^tbl[A-Za-z0-9]{14}$/.test(tableId)) {
    throw new Error("Set an Airtable base ID and table ID");
  }
  const tags = {
    utm_source: campaign_source.trim(),
    utm_medium: campaign_medium.trim(),
    utm_campaign: campaign_name.trim(),
    utm_term: campaign_term.trim(),
    utm_content: campaign_id.trim(),
  };
  if (!tags.utm_source || !tags.utm_medium || !tags.utm_campaign) {
    throw new Error("Enter a campaign source, medium, and name");
  }
  const replacements = Object.entries(tags).filter(([, text]) => text);
  const overridden = new Set(replacements.map(([key]) => key));
  const original = (parts[4] || "").split("&").filter((entry) => {
    if (!entry) return false;
    const key = entry.split("=", 1)[0];
    try {
      return !overridden.has(decodeURIComponent(key.replaceAll("+", " ")));
    } catch {
      return true;
    }
  });
  const query = original.concat(
    replacements.map(([key, text]) => key + "=" + encodeURIComponent(text)),
  );
  const url =
    parts[1].toLowerCase() +
    parts[2].toLowerCase() +
    (parts[3] || "/") +
    "?" +
    query.join("&") +
    (parts[5] || "");
  if (new TextEncoder().encode(url).length > 900)
    throw new Error("Keep the campaign link within 900 UTF-8 bytes");
  return {
    url,
    endpoint: "/v0/" + baseId + "/" + tableId,
    request: { performUpsert: { fieldsToMergeOn: ["URL"] }, records: [{ fields: { URL: url } }] },
  };
}

const settings = {
  website_url: "https://example.com/spring?ref=print#details",
  campaign_id: "poster01",
  campaign_source: "flyer",
  campaign_medium: "print",
  campaign_name: "spring-market",
  campaign_term: "",
  baseId: "YOUR_AIRTABLE_BASE_ID",
  tableId: "YOUR_AIRTABLE_TABLE_ID",
};
return [{ json: prepareCampaign(settings) }];

function checkQrPng(bytes, contentType, statusCode) {
  const png = [137, 80, 78, 71, 13, 10, 26, 10];
  const iend = [0, 0, 0, 0, 73, 69, 78, 68, 174, 66, 96, 130];
  if (
    statusCode !== 200 ||
    contentType?.split(";")[0].trim().toLowerCase() !== "image/png" ||
    bytes?.length < 45 ||
    bytes?.length > 1024 * 1024 ||
    !png.every((byte, index) => bytes?.[index] === byte) ||
    !iend.every((byte, index) => bytes[bytes.length - iend.length + index] === byte)
  ) {
    throw new Error("QuickChart did not return a complete PNG");
  }
  const header = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  if (
    header.getUint32(8) !== 13 ||
    header.getUint32(12) !== 0x49484452 ||
    header.getUint32(16) !== 300 ||
    header.getUint32(20) !== 300
  ) {
    throw new Error("QuickChart did not return the requested 300-pixel QR code");
  }
}

const item = $input.first();
if (!item.binary?.qr) throw new Error("QuickChart QR code is missing");
const bytes = await helpers.getBinaryDataBuffer(0, "qr");
checkQrPng(bytes, item.json.headers?.["content-type"], item.json.statusCode);
return [
  {
    json: $("Set campaign and Airtable fields").first().json,
    binary: { qr: { ...item.binary.qr, fileName: "campaign-qr.png" } },
  },
];

function confirmCampaign({ body, statusCode, url }) {
  if (statusCode !== 200)
    throw new Error(
      "Airtable upsert failed with HTTP " + statusCode + ". Check Airtable before retrying.",
    );
  const record = body?.records?.[0];
  const created = body?.createdRecords;
  const updated = body?.updatedRecords;
  if (
    body?.details ||
    body?.records?.length !== 1 ||
    typeof record?.id !== "string" ||
    !/^rec[A-Za-z0-9]{14}$/.test(record.id) ||
    record.fields?.URL !== url ||
    !Array.isArray(created) ||
    !Array.isArray(updated) ||
    created.length + updated.length !== 1 ||
    (created[0] ?? updated[0]) !== record.id
  ) {
    throw new Error("Airtable did not confirm this campaign link. Check Airtable before retrying.");
  }
  return { url, recordId: record.id, created: created.length === 1 };
}

const saved = $input.first().json;
const qr = $("Check the QR code PNG").first();
return [{ json: confirmCampaign({ ...saved, url: qr.json.url }), binary: qr.binary }];
